192: export function fmtMoney(usd, p, opts = {}) {
193:   const c = getCountry(p).currency;
194:   const value = (Number(usd) || 0) * c.rate;
195:   const abs = Math.abs(value);
196:   if (opts.compact && abs >= 1000000) {
