200:     return (value < 0 ? "-" : "") + c.symbol + new Intl.NumberFormat(c.locale, { notation: "compact", maximumFractionDigits: 1 }).format(abs);
201:   }
202:   const rounded = Math.round(value);
203:   const formatted = new Intl.NumberFormat(c.locale, { maximumFractionDigits: 0 }).format(Math.abs(rounded));
