input.content:
@import url("css/base.css");

:root {
  --nav-h: 62px;
  --card-shadow: 0 3px 14px rgba(20, 52, 66, 0.08);
}

.ico { display: block; flex: 0 0 auto; }

/* ================= GAME SHELL ================= */
.game { background: var(--bg); }
.game-main {
  position: relative;
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.topbar {
  flex: 0 0 auto;
  height: calc(56px + var(--safe-top));
  padding: var(--safe-top) 10px 0;
  display: flex;
  align-items: center;
  gap: 8px;
  color: #fff;
  background: linear-gradient(180deg, #ff4a38 0%, #e5231b 100%);
  box-shadow: 0 2px 12px rgba(180, 20, 14, 0.26);
  z-index: 10;
}
.topbar-btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: #fff;
  flex: 0 0 auto;
}
.topbar-btn:active { background: rgba(255, 255, 255, 0.16); }
.topbar-title { flex: 1; min-width: 0; text-align: center; }
.topbar-title strong {
  display: block;
  font-size: 15px;
  font-weight: 900;
  line-height: 1.1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.topbar-title span {
  display: block;
  margin-top: 1px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.3px;
  color: rgba(255, 255, 255, 0.82);
}
.topbar-money {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 32px;
  padding: 0 9px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.16);
  border: 1px solid rgba(255, 255, 255, 0.28);
  color: #fff;
  font-size: 11.5px;
  font-weight: 900;
  max-width: 106px;
  overflow: hidden;
  white-space: nowrap;
}

/* Identity */
.identity { flex: 0 0 auto; padding: 10px 12px 0; }
.identity-card {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 11px 12px;
  background: #fff;
  border-radius: 18px;
  box-shadow: var(--card-shadow);
  border: 1px solid rgba(20, 52, 66, 0.05);
}
.id-avatar {
  width: 64px;
  height: 64px;
  flex: 0 0 64px;
  border-radius: 50%;
  overflow: hidden;
  background: #e8f2f4;
  box-shadow: 0 0 0 3px #fff, 0 0 0 4.5px #d7e7ea;
}
.id-avatar .avatar-svg { width: 100% !important; height: 100% !important; }
.id-main { flex: 1; min-width: 0; }
.id-name {
  font-family: "Baloo 2", "Nunito", sans-serif;
  font-size: 18px;
  font-weight: 800;
  line-height: 1.08;
  color: var(--blue);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.id-sub {
  margin-top: 1px;
  font-size: 10.5px;
  font-weight: 700;
  color: var(--muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.id-status {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  max-width: 100%;
  margin-top: 4px;
  padding: 3px 8px;
  border-radius: 999px;
  background: #e8f6f8;
  color: var(--teal);
  font-size: 10px;
  font-weight: 900;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.id-status-sub {
  margin-top: 2px;
  font-size: 9.5px;
  font-weight: 700;
  color: #8a99a1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Stats */
.stats-panel { flex: 0 0 auto; padding: 8px 12px 0; }
.stats-card {
  padding: 9px 12px;
  background: #fff;
  border-radius: 16px;
  box-shadow: var(--card-shadow);
  border: 1px solid rgba(20, 52, 66, 0.05);
}
.money-row {
  display: flex;
  gap: 10px;
  padding-bottom: 7px;
  border-bottom: 1px solid #eef3f5;
}
.money-cell { flex: 1; min-width: 0; }
.money-cell span {
  display: block;
  font-size: 8.5px;
  font-weight: 900;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: #8b99a1;
}
.money-cell strong {
  display: block;
  margin-top: 1px;
  font-size: 14px;
  font-weight: 900;
  color: #213842;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.stat-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px 12px;
  padding-top: 8px;
}
.stat-top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 2px;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: #7b8a93;
}
.stat-top b { font-size: 9.5px; color: #4d616b; }
.stat-bar {
  height: 5px;
  border-radius: 999px;
  background: #e9eff2;
  overflow: hidden;
}
.stat-fill {
  display: block;
  height: 100%;
  border-radius: 999px;
  transition: width 0.35s ease;
}
.stat-fill.happy { background: linear-gradient(90deg, #ffc93b, #ffab00); }
.stat-fill.health { background: linear-gradient(90deg, #37c86b, #12973f); }
.stat-fill.smarts { background: linear-gradient(90deg, #55a8e8, #1d6fa8); }
.stat-fill.looks { background: linear-gradient(90deg, #ff8fb1, #e14d80); }
.debt-note {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 6px;
  font-size: 9.5px;
  font-weight: 900;
  color: #c5372c;
}
.extra-stats {
  display: flex;
  gap: 10px;
  margin-top: 6px;
  font-size: 9.5px;
  font-weight: 800;
  color: #7b8a93;
}
.extra-stats span { display: inline-flex; align-items: center; gap: 3px; }

/* Feed */
.feed {
  flex: 1;
  min-height: 0;
  padding: 8px 12px 0;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
  scrollbar-width: none;
}
.feed::-webkit-scrollbar { width: 0; height: 0; }
.feed-inner { padding-bottom: 146px; }
.age-divider {
  display: flex;
  justify-content: center;
  margin: 10px 0 4px;
}
.age-divider span {
  padding: 3px 10px;
  border-radius: 999px;
  background: #e2e9ed;
  color: #81909a;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 1.2px;
  text-transform: uppercase;
}
.log-item {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 5px 0;
}
.log-ico {
  width: 23px;
  height: 23px;
  flex: 0 0 23px;
  margin-top: 1px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: #eef3f5;
  color: #7c8b94;
}
.log-item p {
  flex: 1;
  font-size: 12.5px;
  font-weight: 600;
  line-height: 1.42;
  color: #3a4a54;
}
.log-item.milestone .log-ico { background: #fff3cd; color: #b98600; }
.log-item.milestone p { font-weight: 800; color: #2b3d46; }
.log-item.positive .log-ico { background: #e4f8ec; color: #12973f; }
.log-item.negative .log-ico { background: #ffebe9; color: #d4372c; }
.log-item.money .log-ico { background: #e6f6ea; color: #0f8a3b; }
.log-item.death .log-ico { background: #e9edf0; color: #54666f; }
.feed-more {
  padding: 8px 0;
  text-align: center;
  font-size: 10px;
  font-weight: 800;
  color: #8b99a1;
}

/* Age dock + nav */
.age-dock {
  position: absolute;
  left: 0;
  right: 0;
  bottom: calc(var(--nav-h) + var(--safe-bottom) + 10px);
  display: flex;
  justify-content: center;
  z-index: 30;
  pointer-events: none;
}
.age-btn {
  pointer-events: auto;
  min-width: 192px;
  height: 50px;
  padding: 0 26px;
  border-radius: 999px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  color: #fff;
  background: linear-gradient(180deg, #2fc965 0%, #12973f 100%);
  border: 2px solid rgba(255, 255, 255, 0.4);
  box-shadow: 0 4px 0 #08672a, 0 10px 22px rgba(8, 103, 42, 0.32);
  transition: transform 0.12s ease, box-shadow 0.12s ease;
}
.age-btn:active {
  transform: translateY(2px) scale(0.985);
  box-shadow: 0 2px 0 #08672a, 0 6px 14px rgba(8, 103, 42, 0.3);
}
.age-main { font-size: 15px; font-weight: 900; line-height: 1; letter-spacing: 0.2px; }
.age-sub { margin-top: 2px; font-size: 8.5px; font-weight: 800; letter-spacing: 0.7px; opacity: 0.85; }

.bottomnav {
  flex: 0 0 auto;
  height: calc(var(--nav-h) + var(--safe-bottom));
  padding-bottom: var(--safe-bottom);
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  background: #fff;
  border-top: 1px solid #e1e9ed;
  box-shadow: 0 -6px 18px rgba(20, 52, 66, 0.05);
  z-index: 40;
}
.nav-item {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  color: #8a98a1;
  padding-top: 2px;
}
.nav-item.active { color: var(--red); }
.nav-item.active::before {
  content: "";
  position: absolute;
  top: 0;
  width: 28px;
  height: 3px;
  border-radius: 0 0 4px 4px;
  background: var(--red);
}
.nav-ico { display: grid; place-items: center; }
.nav-label { font-size: 8.5px; font-weight: 900; letter-spacing: 0.1px; }

/* ================= SUBPAGES ================= */
.subpage {
  position: absolute;
  inset: 0;
  z-index: 25;
  display: flex;
  flex-direction: column;
  background: var(--bg);
}
.subpage-head {
  flex: 0 0 auto;
  height: 56px;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 0 8px 0 6px;
  background: #fff;
  border-bottom: 1px solid #e4ecef;
  box-shadow: 0 2px 10px rgba(20, 52, 66, 0.04);
}
.subpage-back {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: #4c6570;
  flex: 0 0 auto;
}
.subpage-back:active { background: #eef4f6; }
.subpage-headtext { flex: 1; min-width: 0; }
.subpage-headtext h2 {
  font-family: "Baloo 2", "Nunito", sans-serif;
  font-size: 17px;
  font-weight: 800;
  line-height: 1.05;
  color: var(--blue);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.subpage-headtext span {
  display: block;
  margin-top: 1px;
  font-size: 9.5px;
  font-weight: 700;
  color: var(--muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.subpage-body {
  flex: 1;
  min-height: 0;
  padding: 12px 12px calc(88px + var(--safe-bottom));
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
  scrollbar-width: none;
}
.subpage-body::-webkit-scrollbar { width: 0; height: 0; }

.panel {
  padding: 13px;
  margin-bottom: 12px;
  background: #fff;
  border-radius: 18px;
  box-shadow: var(--card-shadow);
  border: 1px solid rgba(20, 52, 66, 0.05);
}
.panel-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 8px;
  margin-bottom: 10px;
}
.panel-head h3 {
  font-family: "Baloo 2", "Nunito", sans-serif;
  font-size: 17px;
  font-weight: 800;
  line-height: 1.1;
  color: var(--blue);
}
.panel-head span {
  display: block;
  margin-top: 2px;
  font-size: 10.5px;
  font-weight: 700;
  color: var(--muted);
}
.section-label.market-label { margin: 4px 2px 0; }
.section-label { margin: 0 2px 8px; }
.hint { font-size: 10.5px; font-weight: 700; color: var(--muted); line-height: 1.5; }
.hint.center { text-align: center; margin-top: 10px; }
.muted.tiny { font-size: 11px; font-weight: 700; }

/* Activities */
.cat-head {
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 14px 2px 8px;
}
.cat-ico {
  width: 34px;
  height: 34px;
  border-radius: 11px;
  display: grid;
  place-items: center;
  background: var(--cat, #eef4f6);
  font-size: 17px;
  flex: 0 0 auto;
}
.cat-head strong { display: block; font-size: 13px; font-weight: 900; color: #2b3d46; }
.cat-head small { display: block; font-size: 9.5px; font-weight: 700; color: var(--muted); }
.activity-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-bottom: 4px;
}
.activity-card {
  min-height: 118px;
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 3px;
  text-align: left;
  background: #fff;
  border: 1px solid rgba(20, 52, 66, 0.06);
  border-radius: 15px;
  box-shadow: 0 2px 10px rgba(20, 52, 66, 0.06);
  transition: transform 0.1s ease, opacity 0.15s ease;
}
.activity-card:active { transform: scale(0.98); }
.activity-card.done { opacity: 0.52; }
.activity-top { display: flex; align-items: center; justify-content: space-between; }
.activity-icon { font-size: 22px; line-height: 1; }
.cost {
  padding: 2px 6px;
  border-radius: 999px;
  background: #e9f8ee;
  color: var(--green-2);
  font-size: 9px;
  font-weight: 900;
  white-space: nowrap;
}
.activity-name { font-size: 12.5px; font-weight: 900; color: #2b3d46; line-height: 1.15; }
.activity-desc { flex: 1; font-size: 10px; font-weight: 600; line-height: 1.32; color: var(--muted); }
.effect-chips { display: flex; flex-wrap: wrap; gap: 3px; margin-top: 3px; }
.chip {
  padding: 2px 5px;
  border-radius: 999px;
  background: #f0f4f6;
  color: #687981;
  font-size: 8px;
  font-weight: 900;
  white-space: nowrap;
}
.chip.good { background: #e8f8ee; color: #0f8a3b; }
.chip.bad { background: #ffedeb; color: #c5372c; }

/* Relationships */
.rel-section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 14px 2px 7px;
  font-size: 10.5px;
  font-weight: 900;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: #7e8d96;
}
.rel-section-head span { font-size: 9.5px; color: #9aa8b0; }
.rel-list { overflow: hidden; }
.rel-row {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 11px;
  text-align: left;
  border-bottom: 1px solid #eef3f5;
}
.rel-row:last-child { border-bottom: 0; }
.rel-row:active { background: #f6fafb; }
.rel-avatar {
  width: 44px;
  height: 44px;
  flex: 0 0 44px;
  border-radius: 50%;
  overflow: hidden;
  background: #e8f2f4;
}
.rel-avatar .avatar-svg { width: 100% !important; height: 100% !important; }
.rel-main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.rel-name {
  font-size: 13px;
  font-weight: 900;
  color: #2b3d46;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.rel-sub { font-size: 9.5px; font-weight: 700; color: var(--muted); }
.rel-close {
  flex: 0 0 64px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 3px;
}
.closeness-bar {
  width: 56px;
  height: 5px;
  border-radius: 999px;
  background: #e9eff2;
  overflow: hidden;
}
.closeness-bar i {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, #ff8fb1, #e14d80);
}
.rel-close > span { font-size: 8px; font-weight: 900; color: #8a98a1; }

