```

Career:
```css
.school-strip { display:grid; grid-template-columns:repeat(3,1fr); gap:6px; margin-bottom:10px; }
.school-strip > div { background:#f4f8f9; border-radius:11px; padding:7px 8px; }
.school-strip span { display:block; font-size:8px; font-weight:900; letter-spacing:.7px; text-transform:uppercase; color:#8b99a1; }
.school-strip strong { display:block; font-size:13px; font-weight:900; color:#213842; margin-top:1px; }
.school-note { display:flex; gap:7px; align-items:flex-start; padding:8px 10px; border-radius:11px; background:#eef7f9; color:#3d6570; font-size:10.5px; font-weight:700; line-height:1.4; margin-bottom:9px; }
.school-note .ico { margin-top:1px; color:var(--teal); }
.job-hero { display:flex; align-items:center; gap:10px; margin-bottom:10px; }
.job-hero-icon { width:48;height:48;border-radius:14px;background:#eef7f9;display:grid;place-items:center;font-size:24px;flex:0 0 auto;}
.job-hero-main strong { display:block; font-size:18px; font-weight:900; color:#12973f; }
.job-hero-main strong small { font-size:10px; font-weight:800; color:var(--muted); margin-left:2px; }
.job-hero-main span { display:block; font-size:10px; font-weight:700; color:var(--muted); margin-top:1px; }
.perf-wrap { margin-bottom:10px; }
.perf-label { display:flex; justify-content:space-between; font-size:9px; font-weight:900; text-transform:uppercase; letter-spacing:.6px; color:#7b8a93; margin-bottom:3px; }
.perf-bar { height:6px; border-radius:999; background:#e9eff2; overflow:hidden; }
.perf-bar i { display:block;height:100%;border-radius:999;background:linear-gradient(90deg,#37c86b,#12973f);}
.job-list { display:flex; flex-direction:column; }
.job-row { display:flex; align-items:center; gap:9px; padding:9px 0; border-bottom:1px solid #eef3f5; }
.job-row:last-child { border-bottom:0; }
.job-row-ico { width:38;height:38;border-radius:11px;background:#f4f8f9;display:grid;place-items:center;font-size:19px;flex:0 0 auto;}
.job-row-main { flex:1;min-width:0;display:flex;flex-direction:column;gap:0; }
.job-row-main strong { font-size:12px; font-weight:900; color:#2b3d46; line-height:1.15; }
.job-row-main span { font-size:9px; font-weight:700; color:var(--muted); }
