.job-row.locked { opacity:.62; }
.lock { color:#9aa8b0; display:grid; }
.mini-btn { padding:4px 10px; border-radius:999px; background:#e7f7ee; color:#0f8a3b; font-size:9.5px; font-weight:900; }
.mini-btn:active { background:#d5f0e0; }
.mini-btn.danger { background:#ffedeb; color:#c5372c; }
.pill { padding:2px 7px; border-radius:999px; font-size:8px; font-weight:900; background:#eef3f5; color:#6e7d87; }
