.pill { padding: 2px 7px; border-radius: 999px; background: #eef3f5; color: #6e7d87; font-size: 8px; font-weight: 900; }
.pill.current { background: #e7f7ee; color: #0f8a3b; }

/* Assets */
.worth-card {
  padding: 14px 15px;
  margin-bottom: 12px;
  border-radius: 20px;
  color: #fff;
  background: linear-gradient(145deg, #0d6b7a, #063f49);
  box-shadow: 0 10px 24px rgba(6, 63, 73, 0.24);
}
.worth-main span {
  display: block;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 1.2px;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.62);
}
.worth-main strong {
  display: block;
  margin-top: 1px;
  font-family: "Baloo 2", "Nunito", sans-serif;
  font-size: 28px;
  font-weight: 800;
  line-height: 1.1;
}
.worth-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px 10px;
  margin-top: 11px;
  padding-top: 10px;
  border-top: 1px solid rgba(255, 255, 255, 0.14);
}
.worth-grid span {
  display: block;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.7px;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.55);
}
.worth-grid b { display: block; margin-top: 1px; font-size: 12px; font-weight: 900; }
.worth-grid b.bad, .bank-grid b.bad { color: #ffb3a8; }
.owned-row { display: flex; align-items: center; gap: 9px; padding: 8px 0; border-bottom: 1px solid #eef3f5; }
.owned-row:last-child { border-bottom: 0; }
.asset-ico { flex: 0 0 auto; font-size: 22px; line-height: 1; }
.owned-main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.owned-main strong { font-size: 12px; font-weight: 900; color: #2b3d46; }
.owned-main span { font-size: 9px; font-weight: 700; color: var(--muted); }
.asset-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.asset-card {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 10px;
  text-align: left;
  background: #fff;
  border: 1px solid rgba(20, 52, 66, 0.06);
  border-radius: 15px;
  box-shadow: 0 2px 10px rgba(20, 52, 66, 0.06);
}
.asset-card:active { transform: scale(0.98); }
.asset-top { display: flex; align-items: center; justify-content: space-between; }
.asset-price { font-size: 10px; font-weight: 900; color: #12973f; }
.asset-card > strong { font-size: 11.5px; font-weight: 900; line-height: 1.15; color: #2b3d46; }
.asset-desc { flex: 1; font-size: 9px; font-weight: 600; line-height: 1.3; color: var(--muted); }
.asset-upkeep { font-size: 8px; font-weight: 700; color: #98a5ac; }
.buy-pill {
  align-self: stretch;
  margin-top: 4px;
  padding: 5px 0;
  border-radius: 8px;
  background: #e7f7ee;
  color: #0f8a3b;
  font-size: 9.5px;
  font-weight: 900;
  text-align: center;
}
.empty-state.small { padding: 20px 12px; }
.empty-state.small .big { margin-bottom: 4px; font-size: 30px; }

/* More */
.bank-card {
  padding: 14px 15px;
  margin-bottom: 12px;
  border-radius: 20px;
  color: #fff;
  background: linear-gradient(145deg, #145f91, #0a3d61);
  box-shadow: 0 10px 24px rgba(10, 61, 97, 0.24);
}
.bank-title { display: flex; align-items: center; gap: 6px; margin-bottom: 10px; }
.bank-title strong { font-size: 14px; font-weight: 900; }
.bank-title span { margin-left: auto; font-size: 9px; font-weight: 900; color: #a8e6c0; }
.bank-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px 10px;
  padding-top: 10px;
  border-top: 1px solid rgba(255, 255, 255, 0.14);
}
.bank-grid span {
  display: block;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.7px;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.55);
}
.bank-grid b { display: block; margin-top: 1px; font-size: 12.5px; font-weight: 900; }
.bank-actions { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; margin-top: 11px; }
.bank-btn {
  padding: 8px 0;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.14);
  border: 1px solid rgba(255, 255, 255, 0.22);
  color: #fff;
  font-size: 9.5px;
  font-weight: 900;
}
.bank-btn:active { background: rgba(255, 255, 255, 0.24); }
.progress-line { height: 7px; border-radius: 999px; background: #e9eff2; overflow: hidden; margin-bottom: 10px; }
.progress-line i { display: block; height: 100%; border-radius: 999px; background: linear-gradient(90deg, #ffc93b, #ffab00); }
.ach-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; }
.ach {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 8px;
  border-radius: 12px;
  background: #f7fafb;
  border: 1px solid #e8eff2;
}
.ach.locked { opacity: 0.46; filter: grayscale(0.85); }
.ach-ico { font-size: 19px; line-height: 1.1; }
.ach strong { font-size: 10px; font-weight: 900; line-height: 1.15; color: #2b3d46; }
.ach > span:last-child { font-size: 8.5px; font-weight: 600; line-height: 1.25; color: var(--muted); }
.ach-grid.compact .ach:nth-child(n+7) { display: none; }
.settings-card {
  padding: 2px 12px;
  margin-bottom: 12px;
  background: #fff;
  border-radius: 16px;
  border: 1px solid rgba(20, 52, 66, 0.05);
}
.settings-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 11px 0;
  border-bottom: 1px solid #eef3f5;
}
.settings-row:last-child { border-bottom: 0; }
.settings-row strong { display: block; font-size: 12.5px; font-weight: 900; color: #2b3d46; }
.settings-row span { display: block; margin-top: 1px; font-size: 9.5px; font-weight: 700; color: var(--muted); }
.switch {
  position: relative;
  width: 44px;
  height: 26px;
  flex: 0 0 44px;
  border-radius: 999px;
  background: #dbe4e8;
  transition: background 0.18s;
}
.switch i {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.18);
  transition: transform 0.18s;
}
.switch.on { background: #12973f; }
.switch.on i { transform: translateX(18px); }
.list-row {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 0;
  text-align: left;
  border-bottom: 1px solid #eef3f5;
}
.list-row:last-child { border-bottom: 0; }
.list-icon {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  border-radius: 11px;
  display: grid;
  place-items: center;
  background: #eef7f9;
  color: var(--teal);
}
.list-main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.list-main strong { font-size: 12px; font-weight: 900; color: #2b3d46; }
.list-main span { font-size: 9px; font-weight: 700; color: var(--muted); }
.chev { display: grid; color: #9aa8b0; }
.version-note { padding: 2px 0 8px; text-align: center; font-size: 9px; font-weight: 700; color: #9aa8b0; }
.ribbon-row { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 10px; }
.ribbon {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 8px;
  border-radius: 999px;
  background: #fff6da;
  color: #8a6200;
  font-size: 9px;
  font-weight: 900;
}

/* ================= SHEETS ================= */
.overlay-root { position: fixed; inset: 0; z-index: 90; pointer-events: none; }
.overlay-root:empty { display: none; }
.overlay {
  position: fixed;
  inset: 0;
  z-index: 90;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  background: rgba(6, 16, 21, 0.56);
  backdrop-filter: blur(3px);
  -webkit-backdrop-filter: blur(3px);
  pointer-events: auto;
  animation: fadeIn 0.16s ease;
}
#sheet-root .overlay { align-items: flex-end; }
#drawer-root .overlay { justify-content: flex-start; }

.sheet {
  width: 100%;
  max-width: 440px;
  max-height: 88dvh;
  display: flex;
  flex-direction: column;
  padding-bottom: var(--safe-bottom);
  background: #fff;
  border-radius: 22px 22px 0 0;
  overflow: hidden;
  animation: sheetUp 0.24s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.sheet-grip {
  width: 38px;
  height: 4px;
  flex: 0 0 auto;
  margin: 8px auto 0;
  border-radius: 999px;
  background: #dbe4e8;
}
.sheet-head {
  flex: 0 0 auto;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 16px 8px;
}
.sheet-head h2 {
  font-family: "Baloo 2", "Nunito", sans-serif;
  font-size: 20px;
  font-weight: 800;
  line-height: 1.1;
  color: var(--blue);
}
.sheet-head span { display: block; margin-top: 2px; font-size: 10.5px; font-weight: 700; color: var(--muted); }
.sheet-close {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: #eef4f6;
  color: #61717b;
}
.sheet-body {
  flex: 1;
  min-height: 0;
  padding: 4px 16px 18px;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.sheet-body::-webkit-scrollbar { width: 0; height: 0; }

.confirm-text { font-size: 13px; font-weight: 600; line-height: 1.5; color: #3a4a54; padding: 4px 0 16px; }
.confirm-actions { display: flex; gap: 8px; }
.confirm-actions .btn { flex: 1; }

.amount-wrap { padding-top: 6px; }
.amount-input {
  display: flex;
  align-items: center;
  gap: 6px;
  height: 56px;
  padding: 0 12px;
  border: 1.5px solid #d6e1e6;
  border-radius: 14px;
  background: #f7fafb;
}
.amount-input span { font-size: 18px; font-weight: 900; color: var(--muted); }
.amount-input input {
  flex: 1;
  width: 100%;
  border: 0;
  outline: none;
  background: none;
  font-size: 24px;
  font-weight: 900;
  color: #213842;
}
.amount-hint { margin: 7px 2px 10px; font-size: 10.5px; font-weight: 700; color: var(--muted); }
.quick-row { display: flex; gap: 7px; margin-bottom: 14px; }
.quick-row .toggle-chip { flex: 1; height: 34px; }

.country-list { display: flex; flex-direction: column; gap: 6px; }
.major-list { display: flex; flex-direction: column; gap: 6px; }
.major-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 10px;
  text-align: left;
  border-radius: 13px;
  background: #f7fafb;
  border: 1.5px solid transparent;
}
.major-row:active { background: #eef6f8; border-color: #9ed6e1; }
.major-ico { font-size: 22px; flex: 0 0 auto; }
.major-main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.major-main strong { font-size: 12.5px; font-weight: 900; color: #2b3d46; }
.major-main span { font-size: 9.5px; font-weight: 600; color: var(--muted); }
.major-smarts { flex: 0 0 auto; font-size: 9px; font-weight: 900; color: var(--teal); }

.person-hero { display: flex; flex-direction: column; align-items: center; padding: 4px 0 14px; }
.person-avatar {
  width: 92px;
  height: 92px;
  border-radius: 50%;
  overflow: hidden;
  background: #e8f2f4;
  box-shadow: 0 0 0 4px #fff, 0 0 0 5.5px #d7e7ea;
}
.person-avatar .avatar-svg { width: 100% !important; height: 100% !important; }
.person-close-wrap { width: 100%; max-width: 250px; margin-top: 12px; text-align: center; }
.person-close { height: 7px; border-radius: 999px; background: #e9eff2; overflow: hidden; }
.person-close i { display: block; height: 100%; border-radius: 999px; background: linear-gradient(90deg, #ff8fb1, #e14d80); }
.person-close-wrap > span { display: block; margin-top: 4px; font-size: 10px; font-weight: 800; color: var(--muted); }

.lives-list { display: flex; flex-direction: column; gap: 7px; }
.life-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px;
  text-align: left;
  border-radius: 13px;
  background: #f7fafb;
  border: 1px solid #e8eff2;
}
.life-avatar { width: 46px; height: 46px; flex: 0 0 46px; border-radius: 50%; overflow: hidden; background: #e8f2f4; }
.life-avatar .avatar-svg { width: 100% !important; height: 100% !important; }
.life-main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.life-main strong { font-size: 12px; font-weight: 900; color: #2b3d46; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.life-main span { font-size: 9px; font-weight: 700; color: var(--muted); }
.life-right { flex: 0 0 auto; display: flex; flex-direction: column; align-items: flex-end; gap: 1px; }
.life-right b { font-size: 10px; font-weight: 900; color: #12973f; }
.life-right span { font-size: 8px; font-weight: 700; color: var(--muted); }
.life-detail-hero { display: flex; justify-content: center; padding: 4px 0 12px; }
.life-detail-hero .avatar-svg { border-radius: 50%; box-shadow: 0 0 0 4px #fff, 0 0 0 5.5px #d7e7ea; }
.review-log { padding-top: 4px; }
.review-log .log-age {
  display: inline-block;
  min-width: 18px;
  margin-right: 4px;
  color: #9aa8b0;
  font-size: 9px;
  font-weight: 900;
}

.about-hero { display: flex; justify-content: center; padding: 4px 0 12px; }
.about-text { font-size: 12.5px; font-weight: 600; line-height: 1.55; color: #3a4a54; }
.about-facts { margin-top: 12px; border-top: 1px solid #eef3f5; }
.about-facts > div { display: flex; justify-content: space-between; gap: 12px; padding: 9px 0; border-bottom: 1px solid #eef3f5; }
.about-facts span { font-size: 10.5px; font-weight: 700; color: var(--muted); }
.about-facts b { font-size: 10.5px; font-weight: 900; color: #2b3d46; text-align: right; }

/* ================= MODALS ================= */
.modal-overlay { align-items: center; padding: 16px; }
.modal-card {
  width: 100%;
  max-width: 380px;
  max-height: 86dvh;
  overflow-y: auto;
  padding: 20px 18px 18px;
  background: #fff;
  border-radius: 22px;
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.4);
  animation: popIn 0.22s cubic-bezier(0.2, 0.8, 0.2, 1);
  scrollbar-width: none;
}
.modal-card::-webkit-scrollbar { width: 0; height: 0; }
.event-icon {
  width: 66px;
  height: 66px;
  margin: 0 auto 10px;
  display: grid;
  place-items: center;
  border-radius: 22px;
  background: #fff5d6;
  font-size: 34px;
  box-shadow: inset 0 0 0 1px rgba(180, 130, 0, 0.08);
}
.event-icon.small { width: 58px; height: 58px; font-size: 30px; border-radius: 19px; }
.modal-kicker {
  text-align: center;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  color: #9a7a12;
}
.modal-title {
  margin-top: 3px;
  text-align: center;
  font-family: "Baloo 2", "Nunito", sans-serif;
  font-size: 23px;
  font-weight: 800;
  line-height: 1.1;
  color: var(--blue);
}
.modal-text {
  margin: 9px 0 16px;
  text-align: center;
  font-size: 12.5px;
  font-weight: 600;
  line-height: 1.5;
  color: #3a4a54;
}
.modal-text.result-text { margin-bottom: 18px; }
.choice-list { display: flex; flex-direction: column; gap: 7px; }
.choice-btn {
  width: 100%;
  padding: 11px 13px;
  text-align: left;
  border-radius: 14px;
  background: #f7fafb;
  border: 1.5px solid #e1eaee;
  transition: background 0.12s ease, border-color 0.12s ease;
}
.choice-btn:active { background: #eef6f8; border-color: #9ed6e1; }
.choice-btn:disabled { opacity: 0.45; }
.choice-label { display: block; font-size: 13px; font-weight: 900; line-height: 1.2; color: #2b3d46; }
.choice-sub { display: block; margin-top: 2px; font-size: 9.5px; font-weight: 700; color: var(--muted); }
.result-modal .btn { margin-top: 2px; }

/* ================= DRAWER ================= */
.drawer-overlay { justify-content: flex-start; }
.drawer {
  position: absolute;
  top: 0;
  bottom: 0;
  left: max(0px, calc(50% - 220px));
  width: min(310px, 84vw);
  display: flex;
  flex-direction: column;
  background: #fff;
  box-shadow: 20px 0 60px rgba(0, 0, 0, 0.3);
  animation: drawerIn 0.22s cubic-bezier(0.2, 0.8, 0.2, 1);
  overflow: hidden;
}
.drawer-head {
  position: relative;
  flex: 0 0 auto;
  padding: calc(20px + var(--safe-top)) 18px 18px;
  text-align: center;
  color: #fff;
  background: linear-gradient(160deg, #ff4a38, #c51712);
}
.drawer-close {
  position: absolute;
  top: calc(8px + var(--safe-top));
  right: 8px;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: #fff;
}
.drawer-close:active { background: rgba(255, 255, 255, 0.16); }
.drawer-avatar {
  width: 68px;
  height: 68px;
  margin: 0 auto 8px;
  border-radius: 50%;
  overflow: hidden;
  box-shadow: 0 0 0 4px rgba(255, 255, 255, 0.28);
}
.drawer-avatar .avatar-svg { width: 100% !important; height: 100% !important; }
.drawer-head strong { display: block; font-size: 17px; font-weight: 900; }
.drawer-head span { display: block; margin-top: 1px; font-size: 10.5px; font-weight: 800; color: rgba(255, 255, 255, 0.82); }
.drawer-menu { flex: 1; padding: 8px; overflow-y: auto; }
.drawer-item {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 12px 10px;
  border-radius: 12px;
  text-align: left;
  color: #2b3d46;
  font-size: 13px;
  font-weight: 900;
}
.drawer-item:active { background: #f1f7f9; }
.drawer-item .ico { color: var(--teal); }
.drawer-foot { flex: 0 0 auto; padding: 12px 18px calc(12px + var(--safe-bottom)); font-size: 9px; font-weight: 800; color: #9aa8b0; border-top: 1px solid #eef3f5; }

/* ================= DEATH ================= */
.death-screen {
  background:
    radial-gradient(circle at 20% 0%, #24424f 0%, #0c1a21 55%, #061015 100%);
  color: #fff;
}
.death-scroll { flex: 1; overflow-y: auto; padding: calc(20px + var(--safe-top)) 18px calc(24px + var(--safe-bottom)); scrollbar-width: none; }
.death-scroll::-webkit-scrollbar { width: 0; height: 0; }
.death-top {
  text-align: center;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 4px;
  color: rgba(255, 255, 255, 0.45);
}
.death-hero { display: flex; flex-direction: column; align-items: center; padding: 18px 0 10px; text-align: center; }
.death-avatar {
  width: 118px;
  height: 118px;
  border-radius: 50%;
  overflow: hidden;
  box-shadow: 0 0 0 4px rgba(255, 255, 255, 0.16), 0 16px 40px rgba(0, 0, 0, 0.4);
  filter: grayscale(0.25);
}
.death-avatar .avatar-svg { width: 100% !important; height: 100% !important; }
.death-hero h1 {
  margin-top: 12px;
  font-family: "Baloo 2", "Nunito", sans-serif;
  font-size: 27px;
  font-weight: 800;
  line-height: 1.1;
  color: #fff;
}
.death-years { margin-top: 2px; font-size: 11px; font-weight: 800; letter-spacing: 1.4px; color: #ffd93b; }
.death-cause { margin-top: 8px; font-size: 12px; font-weight: 600; line-height: 1.45; color: rgba(255, 255, 255, 0.8); }
.death-place { margin-top: 2px; font-size: 10px; font-weight: 700; color: rgba(255, 255, 255, 0.5); }
.death-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
  margin: 12px 0;
}
.death-stats > div { padding: 8px 4px; text-align: center; border-radius: 12px; background: rgba(255, 255, 255, 0.07); border: 1px solid rgba(255, 255, 255, 0.08); }
.death-stats span { display: block; font-size: 7.5px; font-weight: 900; letter-spacing: 0.5px; text-transform: uppercase; color: rgba(255, 255, 255, 0.5); }
.death-stats b { display: block; margin-top: 2px; font-size: 15px; font-weight: 900; }
.death-summary {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
  padding: 11px;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.08);
}
.death-summary span { display: block; font-size: 8px; font-weight: 900; letter-spacing: 0.7px; text-transform: uppercase; color: rgba(255, 255, 255, 0.5); }
.death-summary b { display: block; margin-top: 1px; font-size: 11.5px; font-weight: 900; color: #fff; }
.death-ribbons { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 12px; }
.death-ribbons .ribbon { background: rgba(255, 217, 59, 0.14); color: #ffe06b; }
.death-highlights { margin-top: 18px; }
.death-highlights .section-label { color: rgba(255, 255, 255, 0.45); }
.death-log {
  padding: 7px 10px;
  margin-bottom: 5px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.055);
  font-size: 11px;
  font-weight: 600;
  line-height: 1.45;
  color: rgba(255, 255, 255, 0.82);
}
.death-log.milestone { color: #ffe06b; font-weight: 800; }
.death-log.death { color: #ffb3a8; }
.death-actions { display: flex; flex-direction: column; gap: 8px; margin-top: 20px; }
.death-actions .btn-primary { height: 52px; }
.death-actions .btn-ghost { border-color: rgba(255, 255, 255, 0.22); }
.death-foot { margin-top: 14px; text-align: center; font-size: 9.5px; font-weight: 800; letter-spacing: 1px; color: rgba(255, 255, 255, 0.35); }

/* ================= TOAST ================= */
.toast-root {
  position: fixed;
  left: 50%;
  bottom: calc(132px + var(--safe-bottom));
  z-index: 140;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  width: min(400px, 92vw);
  pointer-events: none;
}
.toast {
  max-width: 100%;
  padding: 9px 15px;
  border-radius: 999px;
  background: rgba(25, 40, 48, 0.94);
  color: #fff;
  font-size: 11.5px;
  font-weight: 800;
  line-height: 1.3;
  text-align: center;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
  opacity: 0;
  transform: translateY(10px);
  transition: opacity 0.22s ease, transform 0.22s ease;
}
.toast.show { opacity: 1; transform: translateY(0); }
.toast.positive { background: rgba(15, 138, 59, 0.96); }
.toast.negative { background: rgba(197, 55, 44, 0.96); }
.toast.milestone { background: rgba(138, 98, 0, 0.96); }
.toast.money { background: rgba(15, 138, 59, 0.96); }

/* ================= ANIMATION / RESPONSIVE ================= */
@keyframes bob {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-7px); }
}
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes popIn { from { opacity: 0; transform: scale(0.94) translateY(8px); } to { opacity: 1; transform: scale(1) translateY(0); } }
@keyframes sheetUp { from { transform: translateY(100%); } to { transform: translateY(0); } }
@keyframes drawerIn { from { transform: translateX(-100%); } to { transform: translateX(0); } }

.no-motion *, .no-motion *::before, .no-motion *::after {
  animation-duration: 0.001ms !important;
  animation-iteration-count: 1 !important;
  transition-duration: 0.001ms !important;
}

.title-wordmark { font-size: 39px; line-height: 0.84; }
.title-logo .mark { width: 48px; height: 48px; }

@media (max-height: 720px) {
  .title-avatar-ring { width: 120px; height: 120px; }
  .title-tagline { margin-top: 10px; font-size: 12px; }
  .title-actions { gap: 8px; }
  .title-links { margin-top: 8px; }
  .title-footer { margin-top: 6px; }
  .title-wordmark { font-size: 34px; }
  .title-logo .mark { width: 40px; height: 40px; }
}
@media (max-height: 640px) {
  .title-avatar-ring { width: 96px; height: 96px; }
  .title-float { display: none; }
  .title-tagline { display: none; }
}
@media (max-width: 360px) {
  .activity-grid, .asset-grid, .ach-grid, .action-grid { gap: 6px; }
  .activity-card, .asset-card { padding: 8px; }
  .topbar-title strong { font-size: 13.5px; }
  .topbar-money { max-width: 88px; font-size: 10.5px; }
  .death-stats b { font-size: 13px; }
}

