+}
+.job-row-main { flex: 1; min-width: 0; display: flex; flex-direction: column; }
+.job-row-main strong { font-size: 12px; font-weight: 900; line-height: 1.15; color: #2b3d46; }
+.job-row-main span { font-size: 9px; font-weight: 700; color: var(--muted); }
+.job-row-main small { margin-top: 1px; font-size: 8.5px; font-weight: 700; color: #98a5ac; }
+.job-row-right { flex: 0 0 auto; display: flex; flex-direction: column; align-items: flex-end; gap: 3px; }
