+}
+.worth-grid b { display: block; margin-top: 1px; font-size: 12px; font-weight: 900; }
+.worth-grid b.bad, .bank-grid b.bad { color: #ffb3a8; }
+.owned-row { display: flex; align-items: center; gap: 9px; padding: 8px 0; border-bottom: 1px solid #eef3f5; }
+.owned-row:last-child { border-bottom: 0; }
+.asset-ico { flex: 0 0 auto; font-size: 22px; line-height: 1; }
+.owned-main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
+.owned-main strong { font-size: 12px; font-weight: 900; color: #2b3d46; }
+.owned-main span { font-size: 9px; font-weight: 700; color: var(--muted); }
