+  gap: 10px;
+  padding: 11px 0;
+  border-bottom: 1px solid #eef3f5;
+}
+.settings-row:last-child { border-bottom: 0; }
+.settings-row strong { display: block; font-size: 12.5px; font-weight: 900; color: #2b3d46; }
+.settings-row span { display: block; margin-top: 1px; font-size: 9.5px; font-weight: 700; color: var(--muted); }
+.switch {
+  position: relative;
