import { createRequire } from 'node:module';
const require = createRequire(import.meta.url);
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');

const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
const errors = [];
page.on('pageerror', e => { errors.push('PAGEERROR: ' + e.message); });
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
page.on('response', r => { if (r.status() >= 400) errors.push(`HTTP ${r.status()} ${r.url()}`); });

await page.goto('http://localhost:8123/', { waitUntil: 'networkidle' });
await page.waitForTimeout(600);
await page.screenshot({ path: '/tmp/opencode/01-title.png' });
console.log('title buttons', await page.locator('[data-act]').count());

// New life -> create
await page.click('[data-act="title-new"]');
await page.waitForTimeout(500);
console.log('create visible', await page.locator('#screen-create:not(.hidden)').count());
await page.screenshot({ path: '/tmp/opencode/02-create.png' });

// Change country sheet quickly
await page.click('[data-act="create-country"]');
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/opencode/03-country.png' });
await page.click('[data-act="country-select"][data-code="JP"]');
await page.waitForTimeout(300);

// Start
await page.click('[data-act="create-start"]');
await page.waitForTimeout(600);
console.log('game visible', await page.locator('#screen-game:not(.hidden)').count());
console.log('feed items', await page.locator('.log-item').count());
await page.screenshot({ path: '/tmp/opencode/04-game.png' });

async function clearModal() {
  for (let i = 0; i < 6; i++) {
    if (await page.locator('.event-modal').count()) {
      const choices = page.locator('.event-modal .choice-btn:not([disabled])');
      const n = await choices.count();
      if (!n) { console.log('no enabled choices'); break; }
      await choices.first().click();
      await page.waitForTimeout(250);
      continue;
    }
    if (await page.locator('.result-modal').count()) {
      await page.click('[data-act="result-close"]');
      await page.waitForTimeout(250);
      continue;
    }
    if (await page.locator('.sheet').count()) {
      await page.click('[data-act="sheet-close"]');
      await page.waitForTimeout(150);
      continue;
    }
    break;
  }
}

// Age 12 times, handling modals
for (let i = 0; i < 12; i++) {
  if (await page.locator('#screen-game:not(.hidden)').count() === 0) break;
  await page.click('[data-act="age"]');
  await page.waitForTimeout(220);
  await clearModal();
}
await page.screenshot({ path: '/tmp/opencode/05-aged.png' });
console.log('age text', await page.locator('.topbar-title span').textContent().catch(() => 'n/a'));
console.log('feed items after', await page.locator('.log-item').count());

// Activities tab
await page.click('[data-act="tab"][data-tab="activities"]');
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/opencode/06-activities.png' });
console.log('activity cards', await page.locator('.activity-card').count());

// Relationships tab
await page.click('[data-act="tab"][data-tab="relationships"]');
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/opencode/07-relationships.png' });
await page.click('.rel-row');
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/opencode/08-person.png' });
await page.click('[data-act="sheet-close"]');

// Career tab
await page.click('[data-act="tab"][data-tab="career"]');
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/opencode/09-career.png' });

// Assets tab
await page.click('[data-act="tab"][data-tab="assets"]');
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/opencode/10-assets.png' });

// More tab
await page.click('[data-act="tab"][data-tab="more"]');
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/opencode/11-more.png' });

// Drawer
await page.click('[data-act="open-drawer"]');
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/opencode/12-drawer.png' });
await page.click('[data-act="close-drawer"]');

console.log('ERRORS:', errors.length ? errors.join('\n') : 'none');
await browser.close();

content.text:
We have a bug: `p.stats` becomes NaN? "Cannot create property 'smarts' on number 'NaN'" means `p.stats` is a number NaN. How? In applyEffects in engine:

```js
["happiness", "health", "smarts", "looks", "fame", "karma"].forEach(k => {
  if (typeof effects[k] === "number") p[k === "happiness" || ... ? "stats" : k] = clamp(p[...] + effects[k]);
});
```
This sets p.stats = clamp(p.stats + effects.happiness) instead of p.stats.happiness! That's a serious bug in engine.js. It computes p["stats"] = clamp(p["stats"] + effects[k]), where p.stats is an object -> NaN. So after any event/activity effects, p.stats becomes NaN. Need fix applyEffects.

Fix:
```js
const statKeys = ["happiness","health","smarts","looks"];
for each k: if number effects[k], if statKeys includes k p.stats[k]=clamp(p.stats[k]+effects[k]); else p[k]=clamp(p[k]+effects[k]);
```
Also `applyEffects` p.stats may be object. Let's edit.

Also the age only reached 7 after 12 clicks because some clicks errored? Actually after first error, ageUp throws before save? ageUp increments age then error in driftStats, so age increments but render not called; repeated clicks increment. The modal maybe. Fix and retest.

Also note `applyEffects` rel type for spouse/partner etc. Fine.

Let's fix engine.applyEffects.

