@import url("css/base.css");

:root {
  --nav-h: 62px;
  --card-shadow: 0 3px 14px rgba(20, 52, 66, 0.08);
}

.ico { display: block; flex: 0 0 auto; }

/* ================= GAME SHELL ================= */
.game { background: var(--bg); }
.game-main {
  position: relative;
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.topbar {
  flex: 0 0 auto;
  height: calc(56px + var(--safe-top));
  padding: var(--safe-top) 10px 0;
  display: flex;
  align-items: center;
  gap: 8px;
  color: #fff;
  background: linear-gradient(180deg, #ff4a38 0%, #e5231b 100%);
  box-shadow: 0 2px 12px rgba(180, 20, 14, 0.26);
  z-index: 10;
}
.topbar-btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: #fff;
  flex: 0 0 auto;
}
.topbar-btn:active { background: rgba(255, 255, 255, 0.16); }
.topbar-title { flex: 1; min-width: 0; text-align: center; }
.topbar-title strong {
  display: block;
  font-size: 15px;
  font-weight: 900;
  line-height: 1.1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.topbar-title span {
  display: block;
  margin-top: 1px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.3px;
  color: rgba(255, 255, 255, 0.82);
}
.topbar-money {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 32px;
  padding: 0 9px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.16);
  border: 1px solid rgba(255, 255, 255, 0.28);
  color: #fff;
  font-size: 11.5px;
  font-weight: 900;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.id-status-sub {
  margin-top: 2px;
  font-size: 9.5px;
  font-weight: 700;
  color: #8a99a1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Stats */
.stats-panel { flex: 0 0 auto; padding: 8px 12px 0; }
.stats-card {
  padding: 9px 12px;
  background: #fff;
  border-radius: 16px;
  box-shadow: var(--card-shadow);
  border: 1px solid rgba(20, 52, 66, 0.05);
}
.money-row {
  display: flex;
  gap: 10px;
  padding-bottom: 7px;
  border-bottom: 1px solid #eef3f5;
}
.money-cell { flex: 1; min-width: 0; }
.money-cell span {
  display: block;
  font-size: 8.5px;
  font-weight: 900;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: #8b99a1;
}
.money-cell strong {
  display: block;
  margin-top: 1px;
  font-size: 14px;
  font-weight: 900;
  color: #213842;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.stat-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px 12px;
  padding-top: 8px;
}
.stat-top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 2px;
  font-size: 9px;
  margin-top: 6px;
  font-size: 9.5px;
  font-weight: 800;
  color: #7b8a93;
}
.extra-stats span { display: inline-flex; align-items: center; gap: 3px; }

/* Feed */
.feed {
  flex: 1;
  min-height: 0;
  padding: 8px 12px 0;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
  scrollbar-width: none;
}
.feed::-webkit-scrollbar { width: 0; height: 0; }
.feed-inner { padding-bottom: 146px; }
.age-divider {
  display: flex;
  justify-content: center;
  margin: 10px 0 4px;
}
.age-divider span {
  padding: 3px 10px;
  border-radius: 999px;
  background: #e2e9ed;
  color: #81909a;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 1.2px;
  text-transform: uppercase;
}
.log-item {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 5px 0;
}
.log-ico {
  width: 23px;
  height: 23px;
  flex: 0 0 23px;
  margin-top: 1px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: #eef3f5;
  color: #7c8b94;
}
.log-item p {
  flex: 1;
  font-size: 12.5px;
  font-weight: 600;
  line-height: 1.42;
  color: #3a4a54;
}
.log-item.milestone .log-ico { background: #fff3cd; color: #b98600; }
.log-item.milestone p { font-weight: 800; color: #2b3d46; }
.log-item.positive .log-ico { background: #e4f8ec; color: #12973f; }
.log-item.negative .log-ico { background: #ffebe9; color: #d4372c; }
.log-item.money .log-ico { background: #e6f6ea; color: #0f8a3b; }
.log-item.death .log-ico { background: #e9edf0; color: #54666f; }
.feed-more {
  padding: 8px 0;
  text-align: center;
  font-size: 10px;
  font-weight: 800;
  color: #8b99a1;
}

/* Age dock + nav */
.age-dock {
  position: absolute;
  left: 0;
  right: 0;
  bottom: calc(var(--nav-h) + var(--safe-bottom) + 10px);
  display: flex;
  justify-content: center;
  z-index: 30;
  pointer-events: none;
}
.age-btn {
  pointer-events: auto;
  min-width: 192px;
  height: 50px;
  padding: 0 26px;
  border-radius: 999px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  color: #fff;
  background: linear-gradient(180deg, #2fc965 0%, #12973f 100%);
  border: 2px solid rgba(255, 255, 255, 0.4);
  box-shadow: 0 4px 0 #08672a, 0 10px 22px rgba(8, 103, 42, 0.32);
  transition: transform 0.12s ease, box-shadow 0.12s ease;
}
.age-btn:active {
  transform: translateY(2px) scale(0.985);
  box-shadow: 0 2px 0 #08672a, 0 6px 14px rgba(8, 103, 42, 0.3);
}
.age-main { font-size: 15px; font-weight: 900; line-height: 1; letter-spacing: 0.2px; }
.age-sub { margin-top: 2px; font-size: 8.5px; font-weight: 800; letter-spacing: 0.7px; opacity: 0.85; }

.bottomnav {
  flex: 0 0 auto;
  height: calc(var(--nav-h) + var(--safe-bottom));
  padding-bottom: var(--safe-bottom);
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  background: #fff;
  border-top: 1px solid #e1e9ed;
  box-shadow: 0 -6px 18px rgba(20, 52, 66, 0.05);
  z-index: 40;
}
.nav-item {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  color: #8a98a1;
  padding-top: 2px;
}
.nav-item.active { color: var(--red); }
.nav-item.active::before {
  content: "";
  position: absolute;
  top: 0;
  width: 28px;
  height: 3px;
  border-radius: 0 0 4px 4px;
  background: var(--red);
  background: var(--red);
}
.nav-ico { display: grid; place-items: center; }
.nav-label { font-size: 8.5px; font-weight: 900; letter-spacing: 0.1px; }

/* ================= SUBPAGES ================= */
.subpage {
  position: absolute;
  inset: 0;
  z-index: 25;
  display: flex;
  flex-direction: column;
  background: var(--bg);
}
.subpage-head {
  flex: 0 0 auto;
  height: 56px;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 0 8px 0 6px;
  background: #fff;
  border-bottom: 1px solid #e4ecef;
  box-shadow: 0 2px 10px rgba(20, 52, 66, 0.04);
}
.subpage-back {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: #4c6570;
  flex: 0 0 auto;
}
.subpage-back:active { background: #eef4f6; }
.subpage-headtext { flex: 1; min-width: 0; }
.subpage-headtext h2 {
  font-family: "Baloo 2", "Nunito", sans-serif;
  font-size: 17px;
  font-weight: 800;
  line-height: 1.05;
  color: var(--blue);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.subpage-headtext span {
  display: block;
  margin-top: 1px;
  font-size: 9.5px;
  font-weight: 700;
  color: var(--muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.subpage-body {
  flex: 1;
  min-height: 0;
  padding: 12px 12px calc(88px + var(--safe-bottom));
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
  scrollbar-width: none;
}
.subpage-body::-webkit-scrollbar { width: 0; height: 0; }

.panel {
  padding: 13px;
  margin-bottom: 12px;
  background: #fff;
  border-radius: 18px;
  box-shadow: var(--card-shadow);
  border: 1px solid rgba(20, 52, 66, 0.05);
}
