* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body {
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  position: fixed;
  inset: 0;
  overscroll-behavior: none;
  font-family: "Nunito", "Segoe UI", system-ui, -apple-system, sans-serif;
  color: var(--ink);
  background: radial-gradient(circle at 20% 0%, #1b3a47 0%, #0a171d 55%, #061015 100%);
}
body {
  display: flex;
  align-items: center;
  justify-content: center;
  touch-action: manipulation;
}
button, input, select, textarea {
  font: inherit;
  color: inherit;
}
button {
  border: 0;
  background: none;
  padding: 0;
  cursor: pointer;
  touch-action: manipulation;
}
input { min-width: 0; }
img, svg { max-width: 100%; }
p { margin: 0; }
h1, h2, h3, h4 { margin: 0; }
.hidden { display: none !important; }
.scroll {
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
  scrollbar-width: none;
}
.scroll::-webkit-scrollbar { width: 0; height: 0; }

.app {
  position: relative;
  width: 100%;
  max-width: 440px;
  height: 100dvh;
  max-height: 940px;
  margin: 0 auto;
  background: var(--bg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  border-radius: 26px;
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.55), 0 0 0 1px rgba(255, 255, 255, 0.08);
}
.screen {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  background: var(--bg);
}
@media (max-width: 520px), (max-height: 760px) {
  .app { max-width: none; max-height: none; border-radius: 0; box-shadow: none; }
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 48px;
  padding: 0 18px;
  border-radius: 14px;
  font-weight: 800;
  font-size: 15px;
  line-height: 1.1;
  transition: transform 0.12s ease, box-shadow 0.12s ease, background 0.12s ease, opacity 0.12s ease;
  user-select: none;
}
.btn:active { transform: scale(0.97); }

