const require = createRequire(import.meta.url);
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');

const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });

await page.goto('http://localhost:8123/', { waitUntil: 'networkidle' });
await page.click('[data-act="title-new"]');
await page.waitForTimeout(200);
await page.click('[data-act="create-start"]');
await page.waitForTimeout(500);
await page.screenshot({ path: '/tmp/opencode/20-main.png' });

const box = async (sel) => page.locator(sel).boundingBox();
console.log('stats', await box('#stats'));
console.log('dock', await box('#age-dock'));
console.log('nav', await box('#bottomnav'));
console.log('stats card bottom', (await box('.stats-card')).y + (await box('.stats-card')).height);

await page.click('[data-act="tab"][data-tab="more"]');
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/opencode/21-more.png' });
await page.evaluate(() => { const b = document.querySelector('.subpage-body'); b.scrollTop = b.scrollHeight; });
await page.waitForTimeout(200);
await page.screenshot({ path: '/tmp/opencode/22-more-bottom.png' });
console.log('ERRORS:', errors.length ? errors.join('\n') : 'none');
await browser.close();

