import { createRequire } from 'node:module';
const require = createRequire(import.meta.url);
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');

const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] });
const context = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
const page = await context.newPage();
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
page.on('response', r => { if (r.status() >= 400) errors.push(`HTTP ${r.status()} ${r.url()}`); });

const state = () => page.evaluate(async () => {
  const m = await import('/js/engine.js');
  const p = m.store.profile;
  return p ? {
    age: p.age, alive: p.alive, money: Math.round(p.money), debt: Math.round(p.debt),
    investments: Math.round(p.investments), job: p.job?.title || null, edu: p.education.level,
    stage: p.education.stage, assets: p.assets.length, rels: p.relationships.length,
    happiness: Math.round(p.stats.happiness), health: Math.round(p.stats.health),
    smarts: Math.round(p.stats.smarts), looks: Math.round(p.stats.looks),
    lives: m.store.lives.length, log: p.log.length
  } : null;
});
const patch = (fnBody) => page.evaluate(async (body) => {
  const m = await import('/js/engine.js');
  const p = m.store.profile;
  new Function('p', 'm', body)(p, m);
  m.save();
  return true;
}, fnBody);

async function settle() {
  for (let i = 0; i < 14; i++) {
    if (await page.locator('.modal-card .choice-btn:not([disabled])').count()) {
      await page.locator('.modal-card .choice-btn:not([disabled])').first().click();
      await page.waitForTimeout(180);
      continue;
    }
    if (await page.locator('.result-modal [data-act="result-close"]').count()) {
      await page.locator('.result-modal [data-act="result-close"]').click();
      await page.waitForTimeout(180);
      continue;
    }
    if (await page.locator('.major-row').count()) {
      await page.locator('.major-row').first().click();
      await page.waitForTimeout(180);
      continue;
    }
    if (await page.locator('#sheet-root .sheet').count()) {
      await page.click('[data-act="sheet-close"]');
      await page.waitForTimeout(120);
      continue;
    }
    break;
  }
}

async function ageOne(label) {
  await patch('p.stats.health = 100; p.stats.happiness = Math.max(p.stats.happiness, 70);');
  await page.click('[data-act="age"]');
  await page.waitForTimeout(180);
  await settle();
  const s = await state();
  console.log(`AGE ${label}:`, JSON.stringify(s));
  return s;
}

