import { createRequire } from 'node:module';
const require = createRequire(import.meta.url);
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');

const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] });
const context = await browser.newContext({ viewport: { width: 360, height: 640 }, deviceScaleFactor: 1 });
const page = await context.newPage();
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
page.on('response', r => { if (r.status() >= 400) errors.push(`HTTP ${r.status()} ${r.url()}`); });

const patch = (body) => page.evaluate(async (b) => {
  const m = await import('/js/engine.js');
  new Function('p', 'm', b)(m.store.profile, m); m.save(); return true;
}, body);
const state = () => page.evaluate(async () => {
  const m = await import('/js/engine.js'); const p = m.store.profile;
  return { age: p.age, alive: p.alive, edu: p.education.level, stage: p.education.stage,
    money: Math.round(p.money), lives: m.store.lives.length, rels: p.relationships.length };
});

await page.goto('http://localhost:8123/', { waitUntil: 'networkidle' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'networkidle' });

// create flow with country/city selection
await page.click('[data-act="title-new"]');
await page.waitForTimeout(200);
