import { createRequire } from 'node:module';
const require = createRequire(import.meta.url);
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');

const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] });
const context = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
const page = await context.newPage();
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
page.on('response', r => { if (r.status() >= 400) errors.push(`HTTP ${r.status()} ${r.url()}`); });

const state = () => page.evaluate(async () => {
  const m = await import('/js/engine.js'); const p = m.store.profile;
  return p ? {
    age: p.age, alive: p.alive, money: Math.round(p.money), debt: Math.round(p.debt),
    inv: Math.round(p.investments), job: p.job?.title || null, retired: p.retired,
    edu: p.education.level, stage: p.education.stage, dropped: p.education.droppedOut,
    used: p.usedActivities.length, assets: p.assets.length,
    rels: p.relationships.map(r => ({ type: r.type, name: r.firstName, closeness: Math.round(r.closeness) })),
    stats: { h: Math.round(p.stats.happiness), he: Math.round(p.stats.health), s: Math.round(p.stats.smarts), l: Math.round(p.stats.looks) },
    prison: p.inPrison, flags: p.flags, log: p.log.slice(-3).map(l => l.text)
  } : null;
});

async function seed(body, { reload = true } = {}) {
  await page.evaluate(async (b) => {
    const m = await import('/js/engine.js');
    const p = m.store.profile;
    new Function('p', 'm', b)(p, m);
    m.save();
  }, body);
  if (reload) {
    await page.reload({ waitUntil: 'networkidle' });
    if (await page.locator('[data-act="title-continue"]').count()) {
      await page.click('[data-act="title-continue"]');
      await page.waitForTimeout(350);
    }
  }
}

async function settle() {
  for (let i = 0; i < 10; i++) {
    if (await page.locator('.modal-card .choice-btn:not([disabled])').count()) {
      await page.locator('.modal-card .choice-btn:not([disabled])').first().click();
      await page.waitForTimeout(180);
      continue;
    }
    if (await page.locator('.result-modal [data-act="result-close"]').count()) {
      await page.click('.result-modal [data-act="result-close"]');
      await page.waitForTimeout(180);
      continue;
    }
    if (await page.locator('.major-row').count()) {
      await page.locator('.major-row').first().click();
      await page.waitForTimeout(180);
      continue;
    }
    if (await page.locator('#sheet-root .sheet').count()) {
      await page.click('[data-act="sheet-close"]');
      await page.waitForTimeout(100);
      continue;
    }
    break;
  }
}

const BASE = `
  p.alive = true; p.archived = false; p.age = 25; p.money = 200000; p.debt = 0; p.investments = 0;
  p.stats = { happiness: 80, health: 90, smarts: 80, looks: 80 };
  p.education = { level: 'bachelor', stage: null, gpa: 3.5, major: 'Computer Science', majorId: 'cs', gradAge: null, startAge: 18, droppedOut: false, schoolName: 'Test University' };
  p.job = null; p.retired = false; p.pension = 0; p.inPrison = 0; p.usedActivities = []; p.careerActions = [];
  p.assets = []; p.relationships = p.relationships.filter(r => !['partner','spouse','child','pet','ex'].includes(r.type));
  p.flags = { license: false, vacations: 0, crimes: 0, marriages: 0, businesses: 0, books: 0, lotteryWins: 0, skydives: 0, surgeries: 0 };
`;

await page.goto('http://localhost:8123/', { waitUntil: 'networkidle' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'networkidle' });
await page.click('[data-act="title-new"]');
await page.waitForTimeout(150);
await page.click('[data-act="create-start"]');
await page.waitForTimeout(400);
console.log('BASE CREATED', JSON.stringify(await state()));

// ---------- ACTIVITIES ----------
