121:     p.job.level = (p.job.level || 1) + 1;
122:     p.job.salary = Math.round(p.job.salary * 1.12);
123:     addNote(p, notes, `I earned a promotion at work. My new salary is ${Math.round(p.job.salary)}.`, "positive");
