128: function ageRelationships(p, notes) {
129:   for (const r of p.relationships) {
130:     if (r.alive === false) continue;
131:     r.age += 1;
132:     r.lastInteractions = {};
133: 
134:     if (r.type === "pet") {
135:       if (!r.lifespan) r.lifespan = randomInt(10, 16);
136:       if (r.age >= r.lifespan) {
137:         r.alive = false;
138:         addNote(p, notes, `My ${r.species || "pet"}, ${r.firstName}, passed away. I'll never forget them.`, "negative");
139:         p.stats.happiness = clamp(p.stats.happiness - 12);
140:       }
141:       continue;
142:     }
143: 
144:     if (["friend", "partner", "spouse"].includes(r.type)) {
145:       r.closeness = clamp(r.closeness - randomInt(0, 2));
146:     }
147: 
148:     if (r.type === "child" || r.type === "grandchild") continue;
