150:     const risk = r.age >= 58 ? (r.age - 58) * 0.0042 : 0;
151:     if (Math.random() < risk) {
152:       r.alive = false;
153:       const label = r.type === "mother" ? "My mother" : r.type === "father" ? "My father" : r.type === "spouse" ? "My spouse" : r.type === "grandparent" ? `My ${r.gender === "female" ? "grandmother" : "grandfather"}` : r.type === "sibling" ? `My ${r.gender === "female" ? "sister" : "brother"}` : `My ${r.type}`;
154:       addNote(p, notes, `${label}, ${r.firstName}, passed away at age ${r.age}.`, "death");
155:       const loss = r.type === "spouse" ? 28 : r.type === "mother" || r.type === "father" ? 18 : 9;
156:       p.stats.happiness = clamp(p.stats.happiness - loss);
157:       if (r.type === "spouse") p.flags.married = false;
158: 
159:       if ((r.type === "mother" || r.type === "father" || r.type === "grandparent") && Math.random() < 0.42) {
160:         const inherit = r.type === "grandparent" ? randomInt(1000, 25000) : randomInt(5000, 80000);
161:         p.money += inherit;
162:         addNote(p, notes, `I inherited ${inherit.toLocaleString("en-US")} from ${r.firstName}.`, "money");
163:       }
