192:       addNote(p, notes, change >= 0 ? `My investments gained ${Math.abs(change).toLocaleString("en-US")}.` : `My investments lost ${Math.abs(change).toLocaleString("en-US")}.`, change >= 0 ? "money" : "negative");
193:     }
194:   }
