197: function computeFinancesLocal(p) {
198:   let income = 0;
199:   if (p.job && p.inPrison === 0) income = p.job.salary;
200:   if (p.retired && p.pension) income = p.pension;
201:   let expenses = 0;
202:   if (p.age >= 18) expenses += 9000;
203:   const kids = p.relationships.filter(r => r.type === "child" && r.alive !== false).length;
204:   expenses += kids * 5000;
205:   expenses += p.assets.reduce((s, a) => s + (a.upkeep || 0), 0);
206:   if (p.debt > 0) expenses += Math.round(p.debt * 0.08);
207:   return { income, expenses, net: income - expenses };
