import { createRequire } from 'node:module';
const require = createRequire(import.meta.url);
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');

const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] });
const context = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
const page = await context.newPage();
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
page.on('response', r => { if (r.status() >= 400) errors.push(`HTTP ${r.status()} ${r.url()}`); });

const state = () => page.evaluate(async () => {
  const m = await import('/js/engine.js'); const p = m.store.profile;
  return p ? {
    age: p.age, alive: p.alive, money: Math.round(p.money),
    edu: p.education.level, stage: p.education.stage, gpa: p.education.gpa, major: p.education.major,
    gradAge: p.education.gradAge, dropped: p.education.droppedOut,
    log: p.log.slice(-4).map(l => l.text)
  } : null;
});

async function settle(max = 20) {
  for (let i = 0; i < max; i++) {
    if (await page.locator('.event-modal .choice-btn:not([disabled])').count()) {
      await page.locator('.event-modal .choice-btn:not([disabled])').first().click();
      await page.waitForTimeout(200);
      continue;
    }
    if (await page.locator('.result-modal [data-act="result-close"]').count()) {
      await page.click('.result-modal [data-act="result-close"]');
      await page.waitForTimeout(200);
      continue;
    }
    if (await page.locator('.major-row').count()) {
      await page.locator('.major-row').first().click();
      await page.waitForTimeout(200);
      continue;
    }
    if (await page.locator('#sheet-root .sheet').count()) {
      await page.click('[data-act="sheet-close"]').catch(() => {});
      await page.waitForTimeout(120);
      continue;
    }
    break;
  }
}

await page.goto('http://localhost:8123/', { waitUntil: 'networkidle' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'networkidle' });
await page.click('[data-act="title-new"]');
await page.waitForTimeout(150);
await page.click('[data-act="create-start"]');
await page.waitForTimeout(500);

console.log('BORN', JSON.stringify(await state()));

// Age from 0 to 18, settling any modals each year.
for (let i = 0; i < 18; i++) {
  await page.click('[data-act="age"]');
  await page.waitForTimeout(230);
  await settle();
  const s = await state();
  if (i === 4 || i === 10 || i === 13 || i === 17) {
    console.log(`AGE ${s.age}`, JSON.stringify(s));
  }
}

let s18 = await state();
console.log('AT 18', JSON.stringify(s18));
await page.screenshot({ path: '/tmp/opencode/70-age18.png' });

// Graduation modal should have been handled; now enroll in university via career tab.
await page.click('[data-act="tab"][data-tab="career"]');
await page.waitForTimeout(300);
const enrollBtn = page.locator('[data-act="open-major"][data-kind="college"]');
if (await enrollBtn.count()) {
  await enrollBtn.click();
  await page.waitForTimeout(300);
  await page.locator('.major-row').first().click();
  await page.waitForTimeout(400);
} else {
  console.log('NO COLLEGE BUTTON; career tab HTML snippet:',
    (await page.locator('#screen-game').innerText()).slice(0, 400));
}
console.log('ENROLLED', JSON.stringify(await state()));
await page.screenshot({ path: '/tmp/opencode/71-enrolled.png' });

// Age through 4 years of university.
for (let i = 0; i < 4; i++) {
  await page.click('[data-act="age"]');
  await page.waitForTimeout(230);
  await settle();
  console.log(`UNI YEAR ${i + 1}`, JSON.stringify(await state()));
}

const grad = await state();
console.log('GRADUATED', JSON.stringify(grad));
await page.screenshot({ path: '/tmp/opencode/72-graduated.png' });

console.log('ERRORS:', errors.length ? errors.join('\n') : 'none');
await browser.close();

