import { createRequire } from 'node:module';
const require = createRequire(import.meta.url);
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
await page.goto('http://localhost:8123/', { waitUntil: 'networkidle' });

const result = await page.evaluate(async () => {
  const engine = await import('/js/engine.js');
  const life = await import('/js/lifecycle.js');
  const deaths = [];
  const ages = [];
  // 60 lives followed to age 18.
  for (let i = 0; i < 60; i++) {
    engine.startRandomLife();
    let died = 0;
    for (let a = 0; a < 18; a++) {
      const r = life.ageUp();
      if (r.died) { died = r.age; break; }
    }
    if (died) deaths.push(died);
  }
  // 30 lives followed to natural death.
  for (let i = 0; i < 30; i++) {
    engine.startRandomLife();
    let age = 0;
    for (let a = 0; a < 120; a++) {
      const r = life.ageUp();
      age = r.age ?? age;
      if (r.died) break;
    }
    ages.push(age);
  }
  return {
    earlyDeaths: deaths.length,
    earlyDeathAges: deaths,
    avgLifespan: Math.round(ages.reduce((s, x) => s + x, 0) / ages.length),
    minLifespan: Math.min(...ages),
    maxLifespan: Math.max(...ages),
    lifespans: ages
  };
});
console.log(JSON.stringify(result, null, 2));
await browser.close();

