page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:8123/', { waitUntil: 'networkidle' });

const out = await page.evaluate(async () => {
  const engine = await import('/js/engine.js');
  const life = await import('/js/lifecycle.js');
  const acts = await import('/js/actions-events.js');
  const evmod = await import('/js/events.js');
  const evmore = await import('/js/events-more.js');
  const results = { activities: [], events: [] };

  const rich = () => {
    const p = engine.startRandomLife();
    p.age = 40; p.money = 1000000; p.debt = 0; p.investments = 50000;
    p.stats = { happiness: 70, health: 80, smarts: 85, looks: 80 };
    p.fame = 60; p.karma = 60;
    p.education = { level: 'master', stage: null, gpa: 3.5, major: 'Computer Science', majorId: 'cs', gradAge: 24, startAge: 18, droppedOut: false, schoolName: 'Test University' };
    p.job = { id: 'engineer', title: 'Software Engineer', baseTitle: 'Software Engineer', company: 'Nimbus Tech', icon: '💻', salary: 105000, level: 2, performance: 70, years: 3, field: 'tech', category: 'Full-time' };
    p.flags = { license: false, vacations: 0, crimes: 0, marriages: 0, businesses: 0, books: 0, lotteryWins: 0, skydives: 0, surgeries: 0 };
    p.relationships = p.relationships.filter(r => !['partner','spouse','child','pet','ex'].includes(r.type));
    engine.addPartner({ age: 40, closeness: 85 });
    const spouse = p.relationships.find(r => r.type === 'partner');
    if (spouse) { spouse.type = 'spouse'; p.flags.married = true; }
    engine.addChild();
    p.relationships.push({ id: 'friend-x', firstName: 'Maya', lastName: 'Chen', gender: 'female', type: 'friend', age: 40, closeness: 80, alive: true, appearance: {}, countryCode: p.countryCode, lastInteractions: {}, metAt: 30 });
    return p;
  };

  const list = acts.ACTIVITIES || [];
