  for (const a of Object.values((await import('/js/activities.js')).ACTIVITY_MAP)) {
    try {
      const p = rich();
      p.age = Math.max(18, a.minAge || 18);
      if (a.maxAge != null) p.age = Math.min(p.age, a.maxAge);
      p.money = 1000000;
      const res = acts.doActivity(a.id);
      results.activities.push({ id: a.id, ok: !!res.ok, msg: res.message || '', modal: !!res.modal });
    } catch (e) {
      results.activities.push({ id: a.id, crash: String(e && e.stack || e) });
    }
  }

  // Exercise every event choice with a rich profile.
  const allEvents = [...evmod.EVENTS, ...evmore.EVENTS_MORE];
  for (const ev of allEvents) {
    for (let i = 0; i < (ev.choices || []).length; i++) {
      try {
        const p = rich();
        if (ev.id === 'college_milestone') { p.age = 18; p.education.level = 'hs'; }
        const res = acts.resolveEvent({ ...ev, kicker: 'test', age: p.age }, i);
        results.events.push({ id: ev.id, choice: i, label: ev.choices[i].label, ok: !!res.ok, died: !!res.died, msg: (res.message || '').slice(0, 80) });
      } catch (e) {
        results.events.push({ id: ev.id, choice: i, crash: String(e && e.stack || e) });
      }
    }
  }
  return results;
});

const crashes = [...out.activities, ...out.events].filter(x => x.crash);
const failed = out.events.filter(x => !x.ok);
console.log('ACTIVITIES', out.activities.length, 'crashes', out.activities.filter(x => x.crash).length);
console.log('EVENTS', out.events.length, 'crashes', out.events.filter(x => x.crash).length, 'not-ok', failed.length);
if (crashes.length) console.log('CRASHES', JSON.stringify(crashes, null, 2));
if (failed.length) console.log('NOT OK', JSON.stringify(failed.slice(0, 20), null, 2));
console.log('ERRORS', errors.length ? errors.join('\n') : 'none');
await browser.close();

